const rows = $input.all().map(i => i.json);
const existingTicketNumbers = rows
  .map(r => String(r['Ticket Number'] || '').trim())
  .filter(Boolean);

return rows
  .filter(r => r.Status === 'Pending' && !String(r.conversationId || '').trim())
  .map(r => {
    const row = Object.assign({}, r);
    row._existingTicketNumbers = existingTicketNumbers;
    return { json: row };
  });

const bill = $('Loop Bills for PDF Download').all()[0].json;
const binaryIn = $input.all()[0].binary || {};
const out = { json: Object.assign({}, bill) };
if (binaryIn.data) {
  const safeName = String(bill.bill_no || 'invoice').replace(/[\/\\]/g, '-') + '.pdf';
  out.binary = { file: Object.assign({}, binaryIn.data, { fileName: safeName, fileExtension: 'pdf', mimeType: binaryIn.data.mimeType || 'application/pdf' }) };
}
return out;

const items = $input.all();
const existingSet = new Set();
if (items.length && items[0].json._existingTicketNumbers) {
  items[0].json._existingTicketNumbers.forEach(t => existingSet.add(String(t)));
}

function newTicketNumber() {
  let t;
  do {
    t = String(Math.floor(10000000 + Math.random() * 90000000));
  } while (existingSet.has(t));
  existingSet.add(t);
  return t;
}

const groups = {};
for (const item of items) {
  const bill = item.json;
  const key = bill.customer_id + '||' + bill.guest_name;
  if (!groups[key]) {
    groups[key] = {
      customer_id: bill.customer_id,
      guest_name: bill.guest_name,
      emailTo: bill.email_to,
      emailCc: bill.email_cc,
      cseEmail: bill.cse_email_id,
      cseName: bill.cse_name,
      bills: [],
      binariesByBillNo: new Map()
    };
  }
  groups[key].bills.push(bill);
  if (item.binary && item.binary.file && !groups[key].binariesByBillNo.has(bill.bill_no)) {
    groups[key].binariesByBillNo.set(bill.bill_no, item.binary.file);
  }
}

const output = [];
for (const key of Object.keys(groups)) {
  const g = groups[key];
  g.bills.forEach(b => { b._pdfAttached = g.binariesByBillNo.has(b.bill_no); });
  const hasAllLinks = g.bills.every(b => String(b['CC Avenue Payment Link'] || '').trim() && String(b['Invoice ID'] || '').trim());
  if (hasAllLinks) {
    const outItem = {
      json: {
        customer_id: g.customer_id,
        guest_name: g.guest_name,
        emailTo: g.emailTo,
        emailCc: g.emailCc,
        cseEmail: g.cseEmail,
        cseName: g.cseName,
        ticketNumber: newTicketNumber(),
        bills: g.bills
      },
      binary: {}
    };
    const keys = [];
    let idx = 0;
    for (const bin of g.binariesByBillNo.values()) {
      const k = 'attachment_' + idx;
      outItem.binary[k] = bin;
      keys.push(k);
      idx++;
    }
    outItem.json._binaryKeys = keys.join(',');
    output.push(outItem);
  }
}
return output;

