function parseISTDate(str) {
  if (!str) return null;
  const s = String(str).trim();
  let m = s.match(/^(\d{1,2})-(\d{1,2})-(\d{4})(?:\s+(\d{1,2}):(\d{2}):(\d{2}))?$/);
  if (m) {
    const d = +m[1], mo = +m[2], y = +m[3], h = m[4] ? +m[4] : 0, mi = m[5] ? +m[5] : 0, se = m[6] ? +m[6] : 0;
    return new Date(Date.UTC(y, mo - 1, d, h, mi, se) - 5.5 * 60 * 60 * 1000);
  }
  m = s.match(/^(\d{4})-(\d{1,2})-(\d{1,2})/);
  if (m) {
    return new Date(Date.UTC(+m[1], +m[2] - 1, +m[3]) - 5.5 * 60 * 60 * 1000);
  }
  const d2 = new Date(s);
  return isNaN(d2.getTime()) ? null : d2;
}

