function toCommaList(semicolonList) {
  return String(semicolonList || '').split(';').map(s => s.trim()).filter(Boolean).join(',');
}

const headers = {};
if (thread.inReplyTo) headers['In-Reply-To'] = thread.inReplyTo;
if (thread.references) headers['References'] = thread.references;

const attachments = [];
const binaryKeys = String(thread._binaryKeys || '').split(',').filter(Boolean);
for (const key of binaryKeys) {
  if (!binaryData[key]) continue;
  const buffer = await this.helpers.getBinaryDataBuffer(0, key);
  attachments.push({
    filename: binaryData[key].fileName || (key + '.pdf'),
    content: buffer
  });
}

const info = await transporter.sendMail({
  from: `"${thread.cseName}" <${thread.cseEmail}>`,
  to: toCommaList(thread.toRecipients),
  cc: toCommaList(thread.ccRecipients) || undefined,
  bcc: thread.cseEmail,
  subject: thread.subject,
  html: thread.bodyHtml,
  headers: headers,
  attachments: attachments.length ? attachments : undefined
});

return { json: Object.assign({}, thread, { messageId: info.messageId }) };

const t = $input.all()[0].json;
function nowIST() {
  const ist = new Date(Date.now() + 5.5 * 60 * 60 * 1000);
  const p = n => String(n).padStart(2, '0');
  return p(ist.getUTCDate()) + '-' + p(ist.getUTCMonth() + 1) + '-' + ist.getUTCFullYear() + ' ' + p(ist.getUTCHours()) + ':' + p(ist.getUTCMinutes()) + ':' + p(ist.getUTCSeconds());
}
const now = nowIST();
const newBillNos = new Set((t.bills || []).map(b => b.bill_no));

const MAX_CELL_CHARS = 45000;
let storedBody = t.bodyHtml || '';
if (storedBody.length > MAX_CELL_CHARS) {
  storedBody = storedBody.slice(0, MAX_CELL_CHARS) + '<p><em>[Trimmed to fit the sheet cell size limit - the full email as actually sent is longer than this stored copy.]</em></p>';
}

// 2026-09-15: Accenture never gets a PDF attached in this regeneration email (Filter Regen
// Bills Having PDF excludes them) - the invoice is only ever actually shared when the client
// requests it (WF4's InvoiceRequest bucket) or in the final thank-you mail (WF5). So Invoice
// Emailed must never be set here for Accenture, regardless of newBillNos.
const isAccenture = String(t.customer_id || '').toUpperCase().includes('ACCENTURE');

const output = [];
for (const bill of (t.allBills || [])) {
  const row = {
    bill_no: bill.bill_no,
    duty_slip_no: bill.duty_slip_no,
    'Message ID': t.messageId,
    'Last Reminder Sent': now,
    'Last Updated': now,
    'Last Email Body': storedBody
  };
  if (newBillNos.has(bill.bill_no)) {
    row['Invoice Regenerated'] = '';
    if (!isAccenture) {
      row['Invoice Emailed'] = now;
    }
  }
  output.push({ json: row });
}
return output;

